package com.universalplatform.integration;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="identity_provider",uniqueConstraints=@UniqueConstraint(name="uq_identity_provider_tenant_key",columnNames={"tenant_id","provider_key"})) class IdentityProvider { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false,length=64) private String providerKey; @Column(nullable=false,length=400) private String issuer; @Column(nullable=false,length=300) private String authorizationEndpoint; @Column(nullable=false,length=200) private String clientId; @Column(length=500) private String clientSecretCiphertext; @Column(nullable=false,length=500) private String redirectUri; @Column(nullable=false,length=500) private String scopes; @Column(nullable=false) private boolean enabled; @Version private long version; @Column(nullable=false) private Instant updatedAt; protected IdentityProvider(){} IdentityProvider(UUID id,UUID tenantId,String key,String issuer,String auth,String client,String secret,String redirect,String scopes,Instant now){this.id=id;this.tenantId=tenantId;this.providerKey=key;this.issuer=issuer;this.authorizationEndpoint=auth;this.clientId=client;this.clientSecretCiphertext=secret;this.redirectUri=redirect;this.scopes=scopes;this.enabled=true;this.updatedAt=now;} UUID id(){return id;} UUID tenantId(){return tenantId;} String providerKey(){return providerKey;} String issuer(){return issuer;} String authorizationEndpoint(){return authorizationEndpoint;} String clientId(){return clientId;} String clientSecretCiphertext(){return clientSecretCiphertext;} String redirectUri(){return redirectUri;} String scopes(){return scopes;} boolean enabled(){return enabled;} long version(){return version;} void update(String issuer,String auth,String client,String secret,String redirect,String scopes,Instant now){this.issuer=issuer;this.authorizationEndpoint=auth;this.clientId=client;this.clientSecretCiphertext=secret;this.redirectUri=redirect;this.scopes=scopes;this.enabled=true;this.updatedAt=now;} void disable(){enabled=false;} }
